<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {t,locale} from '../i18n'
import {LABELS,type AgentKind,type Run} from '../../shared/types'
import {stages} from '../content'
import Icon from './Icon.vue'
import Markdown from './Markdown.vue'
const props=defineProps<{kind:AgentKind;run?:Run;messages?:import('../../shared/types').Message[]}>()
const emit=defineEmits<{close:[];notify:[message:string]}>()
const dialog=ref<HTMLDialogElement>(),round=ref('all'),clock=ref(Date.now()),removing=ref(false)
let timer:ReturnType<typeof setInterval>
onMounted(()=>{dialog.value?.showModal();timer=setInterval(()=>clock.value=Date.now(),1000)});onUnmounted(()=>clearInterval(timer))
const attempts=computed(()=>props.run?.attempts?.filter(a=>a.kind===props.kind)||[])
const rounds=computed(()=>[...new Set(attempts.value.map(a=>a.round))].sort((a,b)=>b-a))
const visible=computed(()=>attempts.value.filter(a=>round.value==='all'||a.round===Number(round.value)).slice().reverse())
const excluded=computed(()=>props.run?.excludedAgents?.find(a=>a.kind===props.kind))
const roleLabels:Record<string,string>={contributor:'讨论成员',moderator:'讨论主持者',finalizer:'成果负责人',producer:props.run?.mode==='review'?'制作者':'成果负责人',reviewer:'检查者',approval:'版本确认'}
const statusLabels:Record<string,string>={running:'进行中',completed:'本轮已完成',failed:'调用失败',cancelled:'已取消',interrupted:'已中断'}
const time=(at:string)=>new Date(at).toLocaleTimeString(locale.value==='zh'?'zh-CN':'en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'})
async function remove(){if(!props.run)return;removing.value=true;try{await window.qwork!.removeAgent(props.run.id,props.kind)}catch(error:any){emit('notify',error.message)}finally{removing.value=false}}
</script>
<template><dialog ref="dialog" class="dialog trace-drawer" @cancel.prevent="emit('close')"><header class="dialog-header"><div><div class="trace-person"><span class="avatar" :data-agent="kind">{{ LABELS[kind].slice(0,1) }}</span><h2>{{ LABELS[kind] }}</h2></div><p>{{ t('按轮次查看调用、工具、返回与异常事件') }}</p></div><button class="icon-button" :aria-label="t('关闭')" @click="emit('close')"><Icon name="close"/></button></header><div class="trace-controls"><label v-if="run?.mode!=='parallel'">{{ t('轮次') }}<select v-model="round"><option value="all">{{ t('全部轮次') }}</option><option v-for="n in rounds" :key="n" :value="String(n)">{{ t('第 {round} 轮',{round:n}) }}</option></select></label><span>{{ attempts.length }} {{ t('次调用') }}</span><button v-if="run&&['running','waiting'].includes(run.status)&&!excluded" class="button subtle" :disabled="removing" @click="remove"><Icon name="stop" :size="14"/>{{ t('停止并移出') }}</button></div><div class="trace-content"><section v-if="excluded" class="trace-failure" role="alert"><strong>{{ t('该 Agent 已移出当前群聊') }}</strong><p>{{ t(excluded.reason) }}</p><small>{{ excluded.code }} · {{ time(excluded.at) }}</small></section><p v-if="!attempts.length" class="trace-empty">{{ run?t('尚无此成员的执行记录；旧版本历史不会补造过程。'):t('开始任务后，这里会显示真实执行事件。') }}</p><details v-for="attempt in visible" :key="attempt.id" class="attempt-card" :open="attempt.id===attempts.at(-1)?.id"><summary><div><strong>{{ run?.mode==='parallel'?t('单轮分析'):t('第 {round} 轮',{round:attempt.round}) }} · {{ stages[attempt.stage] }}</strong><small>{{ t(roleLabels[attempt.role]||attempt.role) }} · {{ time(attempt.startedAt) }}</small></div><span :class="['status-chip',attempt.status==='failed'?'failed':attempt.status]">{{ t(statusLabels[attempt.status]) }}</span><Icon name="down" :size="14"/></summary><div class="attempt-metrics"><span>{{ Math.max(0,Math.floor(((attempt.finishedAt?Date.parse(attempt.finishedAt):clock)-Date.parse(attempt.startedAt))/1000)) }}s {{ t('耗时') }}</span><span>{{ attempt.responseChars }} {{ t('已返回字符') }}</span><span v-if="attempt.status==='running'">{{ t('距最近活动') }} {{ Math.max(0,Math.floor((clock-Date.parse(attempt.lastActivityAt))/1000)) }}s</span></div><div class="attempt-io"><strong>{{ t("任务与本次职责") }}</strong><Markdown :text="attempt.inputSummary||run?.task||''"/><strong>{{ t("输出") }}</strong><Markdown :text="messages?.find(m=>m.id===attempt.outputMessageId)?.text||''"/><p v-if="attempt.fault">{{ t(attempt.fault.message) }}</p><p v-else>{{ t(statusLabels[attempt.status]) }}</p></div><p v-if="attempt.droppedEvents" class="trace-note">{{ t('事件过多，仅保留启动记录与最近事件。') }}</p></details></div><footer class="trace-footer">{{ t('仅展示可公开的执行事件，不包含模型内部思维、原始提示词或凭据。') }}</footer></dialog></template>
<style scoped>
.trace-drawer{margin:0 0 0 auto;width:620px;max-width:90vw;height:100vh;max-height:100vh;border-radius:14px 0 0 14px;display:flex;flex-direction:column}.trace-drawer:not([open]){display:none}.trace-person{display:flex;align-items:center;gap:10px}.dialog-header p{font-size:12px;color:var(--color-7c8d72,#7c8d72);margin-top:11px;line-height:1.7}.trace-controls{display:flex;align-items:center;gap:13px;padding:14px 22px;background:var(--color-edf3e7,#edf3e7);border-bottom:1px solid var(--color-dde5d5,#dde5d5);font-size:12px}.trace-controls label{display:flex;align-items:center;gap:9px}.trace-controls select{padding:6px 10px;font-size:12px}.trace-controls>span{color:var(--color-88987a,#88987a)}.trace-controls>.button{margin-left:auto;font-size:11px;padding:8px 10px}.trace-content{padding:20px 22px;overflow:auto;flex:1;min-height:0}.trace-failure{background:var(--color-fbede4,#fbede4);border:1px solid var(--color-e5c6b1,#e5c6b1);border-radius:9px;padding:15px;font-size:12px;color:var(--color-9b6047,#9b6047);line-height:1.8;margin-bottom:18px}.trace-failure>p{margin:8px 0;overflow-wrap:anywhere}.trace-failure small{font-size:10px;opacity:.8}.trace-empty{font-size:13px;line-height:1.9;color:var(--color-8a997b,#8a997b);padding:20px 0}.attempt-card{background:var(--color-fffefb,#fffefb);border:1px solid var(--color-dce5d3,#dce5d3);border-radius:10px;margin-bottom:13px}.attempt-card>summary{list-style:none;display:flex;align-items:center;gap:10px;padding:15px;cursor:pointer}.attempt-card>summary::-webkit-details-marker{display:none}.attempt-card>summary>div{flex:1}.attempt-card>summary strong{display:block;font-size:13px}.attempt-card>summary small{display:block;margin-top:6px;font-size:11px;color:var(--color-8b9a7d,#8b9a7d)}.attempt-metrics{display:flex;gap:14px;border-top:1px solid var(--color-e7ecdf,#e7ecdf);padding:12px 15px;font-size:11px;color:var(--color-81936e,#81936e);flex-wrap:wrap}.trace-events{list-style:none;margin:0;padding:0 15px 15px}.trace-events>li{display:flex;gap:15px;border-left:1px solid var(--color-dde6d2,#dde6d2);margin-left:3px;padding:10px 0 10px 13px;position:relative}.trace-events>li::before{content:'';width:6px;height:6px;border-radius:50%;background:var(--color-94b482,#94b482);position:absolute;left:-4px;top:16px}.trace-events time{font-size:10px;color:var(--color-9aa78d,#9aa78d);white-space:nowrap;margin-top:2px}.trace-events strong{font-size:12px;font-weight:500;line-height:1.8}.trace-events p{font-size:11px;color:var(--color-899c78,#899c78);line-height:1.9;overflow-wrap:anywhere;white-space:pre-wrap;margin-top:4px}.trace-events code{display:block;font-size:10px;color:var(--color-ab765a,#ab765a);margin-top:6px}.trace-events .failure,.trace-events .removed{color:var(--color-ac674d,#ac674d)}.trace-events .failure::before,.trace-events .removed::before{background:var(--color-c07d5f,#c07d5f)}.trace-events .warning{color:var(--color-a18243,#a18243)}.trace-note,.trace-footer{font-size:11px;line-height:1.9;color:var(--color-90a080,#90a080)}.trace-note{padding:0 15px 12px}.trace-footer{border-top:1px solid var(--color-e0e7d7,#e0e7d7);padding:14px 23px;background:var(--color-f1f5eb,#f1f5eb)}
</style>
